INSERT INTO repo_subtopics (subtopic_id, name, subtopic_no, description, subtopic_sd_id, review_status, status, version) VALUES ('SUB_COURSE_051_M6_S2', 'monitoring', '2', 'monitoring: Systematic collection and review of observations or measurements over time to determine status, compliance, performance, or change against defined criteria. In Compliance and Post-Approval Monitoring, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_051_M6_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_051_M6_S3', 'reporting', '3', 'reporting: Structured communication of specified information, measurements, findings, or compliance information to an identified recipient under defined requirements. In Compliance and Post-Approval Monitoring, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_051_M6_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_051_M6_S4', 'non-compliance', '4', 'non-compliance: non-compliance in Environmental Impact Assessment Law concerns legal rules, institutional mechanisms, duties, procedures, and compliance considerations governing non-compliance. In Compliance and Post-Approval Monitoring, the focus is on the analysis, design, implementation, interpretation, or evaluation of non-compliance within Environmental Impact Assessment Law, particularly where the Compliance and Post-Approval Monitoring module establishes its technical context.', 'SSD_COURSE_051_M6_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_051_M6_S5', 'adaptive management', '5', 'adaptive management: Adjusting environmental management measures in response to monitoring results, new evidence, or changing conditions. In Compliance and Post-Approval Monitoring, the focus is on the analysis, design, implementation, interpretation, or evaluation of adaptive management within Environmental Impact Assessment Law, particularly where the Compliance and Post-Approval Monitoring module establishes its technical context.', 'SSD_COURSE_051_M6_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_051_M7_S1', 'standing', '1', 'standing refers to the legal entitlement of a person or organisation to bring a matter before a court or tribunal. In EIA Litigation and Comparative Approaches, the focus is on the analysis, design, implementation, interpretation, or evaluation of standing within Environmental Impact Assessment Law, particularly where the EIA Litigation and Comparative Approaches module establishes its technical context.', 'SSD_COURSE_051_M7_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_051_M7_S2', 'remedies', '2', 'remedies: remedies in Environmental Impact Assessment Law concerns legal rules, institutional mechanisms, duties, procedures, and compliance considerations governing remedies. In EIA Litigation and Comparative Approaches, the focus is on the analysis, design, implementation, interpretation, or evaluation of remedies within Environmental Impact Assessment Law, particularly where the EIA Litigation and Comparative Approaches module establishes its technical context.', 'SSD_COURSE_051_M7_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_051_M7_S3', 'evidentiary issues', '3', 'evidentiary issues: Questions about the relevance, reliability, admissibility, and treatment of evidence in environmental proceedings. In EIA Litigation and Comparative Approaches, the focus is on the analysis, design, implementation, interpretation, or evaluation of evidentiary issues within Environmental Impact Assessment Law, particularly where the EIA Litigation and Comparative Approaches module establishes its technical context.', 'SSD_COURSE_051_M7_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_051_M7_S4', 'comparative EIA regimes', '4', 'comparative EIA regimes: Comparison of how different legal systems structure environmental assessment, participation, approval, and review. In EIA Litigation and Comparative Approaches, the focus is on the analysis, design, implementation, interpretation, or evaluation of comparative EIA regimes within Environmental Impact Assessment Law, particularly where the EIA Litigation and Comparative Approaches module establishes its technical context.', 'SSD_COURSE_051_M7_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_052_M1_S1', 'climate institutions', '1', 'climate institutions: Public and international bodies responsible for developing, coordinating, implementing, or reviewing climate policy and law. In Climate Governance and Legal Frameworks, the focus is on the analysis, design, implementation, interpretation, or evaluation of climate institutions within Climate Change Law and Policy, particularly where the Climate Governance and Legal Frameworks module establishes its technical context.', 'SSD_COURSE_052_M1_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_052_M1_S2', 'legislative instruments', '2', 'legislative instruments: Laws or delegated legislative instruments that establish legally binding powers, duties, standards, procedures, or institutional arrangements. In Climate Governance and Legal Frameworks, the focus is on the analysis, design, implementation, interpretation, or evaluation of legislative instruments within Climate Change Law and Policy, particularly where the Climate Governance and Legal Frameworks module establishes its technical context.', 'SSD_COURSE_052_M1_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_052_M1_S3', 'executive policy', '3', 'executive policy: executive policy in Climate Change Law and Policy concerns legal rules, institutional mechanisms, duties, procedures, and compliance considerations governing executive policy. In Climate Governance and Legal Frameworks, the focus is on the analysis, design, implementation, interpretation, or evaluation of executive policy within Climate Change Law and Policy, particularly where the Climate Governance and Legal Frameworks module establishes its technical context.', 'SSD_COURSE_052_M1_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_052_M1_S4', 'federalism', '4', 'federalism: Allocation of climate-related powers and responsibilities among national, state, provincial, or local governments. In Climate Governance and Legal Frameworks, the focus is on the analysis, design, implementation, interpretation, or evaluation of federalism within Climate Change Law and Policy, particularly where the Climate Governance and Legal Frameworks module establishes its technical context.', 'SSD_COURSE_052_M1_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_052_M2_S1', 'emissions regulation', '1', 'emissions regulation: Legal and policy measures that set requirements or limits for the release of pollutants or greenhouse gases and establish monitoring or compliance duties. In Mitigation Law and Policy, the focus is on the analysis, design, implementation, interpretation, or evaluation of emissions regulation within Climate Change Law and Policy, particularly where the Mitigation Law and Policy module establishes its technical context.', 'SSD_COURSE_052_M2_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_052_M2_S2', 'carbon pricing concepts', '2', 'carbon pricing concepts: Policy approaches that attach an economic cost to greenhouse-gas emissions, including taxes and emissions trading. In Mitigation Law and Policy, the focus is on the analysis, design, implementation, interpretation, or evaluation of carbon pricing concepts within Climate Change Law and Policy, particularly where the Mitigation Law and Policy module establishes its technical context.', 'SSD_COURSE_052_M2_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_052_M2_S3', 'energy regulation', '3', 'energy regulation: Legal and policy measures governing energy production, supply, use, markets, efficiency, emissions, or related infrastructure. In Mitigation Law and Policy, the focus is on the analysis, design, implementation, interpretation, or evaluation of energy regulation within Climate Change Law and Policy, particularly where the Mitigation Law and Policy module establishes its technical context.', 'SSD_COURSE_052_M2_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_052_M2_S4', 'sectoral measures', '4', 'sectoral measures: Climate policies targeted at sectors such as energy, transport, buildings, industry, agriculture, or land use. In Mitigation Law and Policy, the focus is on the analysis, design, implementation, interpretation, or evaluation of sectoral measures within Climate Change Law and Policy, particularly where the Mitigation Law and Policy module establishes its technical context.', 'SSD_COURSE_052_M2_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_052_M3_S1', 'adaptation duties', '1', 'adaptation duties: Legal or policy responsibilities to assess climate risks and take measures that reduce vulnerability or exposure. In Adaptation and Resilience, the focus is on the analysis, design, implementation, interpretation, or evaluation of adaptation duties within Climate Change Law and Policy, particularly where the Adaptation and Resilience module establishes its technical context.', 'SSD_COURSE_052_M3_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_052_M3_S2', 'disaster risk', '2', 'disaster risk refers to the potential for climate-related hazards to cause losses, shaped by hazard, exposure, vulnerability, and capacity. In Adaptation and Resilience, the focus is on the analysis, design, implementation, interpretation, or evaluation of disaster risk within Climate Change Law and Policy, particularly where the Adaptation and Resilience module establishes its technical context.', 'SSD_COURSE_052_M3_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_052_M3_S3', 'resilience planning', '3', 'resilience planning: Planning that identifies climate or other hazards, assesses vulnerability, and selects measures that improve the capacity of systems or communities to withstand and recover from disruption. In Adaptation and Resilience, the focus is on the analysis, design, implementation, interpretation, or evaluation of resilience planning within Climate Change Law and Policy, particularly where the Adaptation and Resilience module establishes its technical context.', 'SSD_COURSE_052_M3_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_052_M3_S4', 'vulnerable communities', '4', 'vulnerable communities: Groups or communities facing disproportionate climate risks because of exposure, sensitivity, or limited adaptive capacity. In Adaptation and Resilience, the focus is on the analysis, design, implementation, interpretation, or evaluation of vulnerable communities within Climate Change Law and Policy, particularly where the Adaptation and Resilience module establishes its technical context.', 'SSD_COURSE_052_M3_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_052_M4_S1', 'climate risk disclosure', '1', 'climate risk disclosure: climate risk disclosure in Climate Change Law and Policy concerns legal rules, institutional mechanisms, duties, procedures, and compliance considerations governing climate risk disclosure. In Climate Finance and Disclosure, the focus is on the analysis, design, implementation, interpretation, or evaluation of climate risk disclosure within Climate Change Law and Policy, particularly where the Climate Finance and Disclosure module establishes its technical context.', 'SSD_COURSE_052_M4_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_052_M4_S2', 'sustainable finance', '2', 'sustainable finance: Financial practices and instruments that direct capital while accounting for environmental, climate, social, and governance risks. In Climate Finance and Disclosure, the focus is on the analysis, design, implementation, interpretation, or evaluation of sustainable finance within Climate Change Law and Policy, particularly where the Climate Finance and Disclosure module establishes its technical context.', 'SSD_COURSE_052_M4_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_052_M4_S3', 'fiduciary considerations', '3', 'fiduciary considerations: Duties and decision factors relevant to how trustees, directors, or fiduciaries consider climate-related risks and opportunities. In Climate Finance and Disclosure, the focus is on the analysis, design, implementation, interpretation, or evaluation of fiduciary considerations within Climate Change Law and Policy, particularly where the Climate Finance and Disclosure module establishes its technical context.', 'SSD_COURSE_052_M4_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_052_M4_S4', 'reporting', '4', 'reporting: Structured communication of specified information, measurements, findings, or compliance information to an identified recipient under defined requirements. In Climate Finance and Disclosure, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_052_M4_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_052_M5_S1', 'United Nations Framework Convention on Climate Change (UNFCCC)', '1', 'UNFCCC: United Nations Framework Convention on Climate Change, the foundational international treaty framework for global climate cooperation. In International Climate Law, the focus is on the analysis, design, implementation, interpretation, or evaluation of UNFCCC within Climate Change Law and Policy, particularly where the International Climate Law module establishes its technical context.', 'SSD_COURSE_052_M5_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_052_M5_S2', 'Paris Agreement', '2', 'Paris Agreement refers to the 2015 international climate agreement establishing a framework for national mitigation, adaptation, finance, transparency, and cooperation. In International Climate Law, the focus is on the analysis, design, implementation, interpretation, or evaluation of Paris Agreement within Climate Change Law and Policy, particularly where the International Climate Law module establishes its technical context.', 'SSD_COURSE_052_M5_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_052_M5_S3', 'nationally determined contributions', '3', 'nationally determined contributions: National climate plans communicated under the Paris Agreement describing intended mitigation and other climate actions. In International Climate Law, the focus is on the analysis, design, implementation, interpretation, or evaluation of nationally determined contributions within Climate Change Law and Policy, particularly where the International Climate Law module establishes its technical context.', 'SSD_COURSE_052_M5_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_052_M5_S4', 'transparency framework', '4', 'transparency framework refers to the Paris Agreement system for reporting and reviewing information on emissions, progress, support, and climate actions. In International Climate Law, the focus is on the analysis, design, implementation, interpretation, or evaluation of transparency framework within Climate Change Law and Policy, particularly where the International Climate Law module establishes its technical context.', 'SSD_COURSE_052_M5_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_052_M6_S1', 'rights-based claims', '1', 'rights-based claims: Climate-related legal claims grounded in rights, duties, or protections recognised by applicable law. In Climate Litigation and Accountability, the focus is on the analysis, design, implementation, interpretation, or evaluation of rights-based claims within Climate Change Law and Policy, particularly where the Climate Litigation and Accountability module establishes its technical context.', 'SSD_COURSE_052_M6_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_052_M6_S2', 'government duties', '2', 'government duties: Legal obligations of public authorities to act, regulate, disclose, protect, or consider climate-related risks. In Climate Litigation and Accountability, the focus is on the analysis, design, implementation, interpretation, or evaluation of government duties within Climate Change Law and Policy, particularly where the Climate Litigation and Accountability module establishes its technical context.', 'SSD_COURSE_052_M6_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_052_M6_S3', 'corporate claims', '3', 'corporate claims: Legal or regulatory claims concerning corporate climate representations, conduct, disclosure, or responsibilities. In Climate Litigation and Accountability, the focus is on the analysis, design, implementation, interpretation, or evaluation of corporate claims within Climate Change Law and Policy, particularly where the Climate Litigation and Accountability module establishes its technical context.', 'SSD_COURSE_052_M6_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_052_M6_S4', 'causation', '4', 'causation refers to the legal and factual link between an alleged climate-related act or omission and a claimed harm. In Climate Litigation and Accountability, the focus is on the analysis, design, implementation, interpretation, or evaluation of causation within Climate Change Law and Policy, particularly where the Climate Litigation and Accountability module establishes its technical context.', 'SSD_COURSE_052_M6_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_052_M7_S1', 'policy instruments', '1', 'policy instruments: Tools through which public authorities seek to influence behaviour, allocate resources, regulate activity, or achieve defined policy objectives. In Climate Policy Implementation, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_052_M7_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_052_M7_S2', 'regulatory coordination', '2', 'regulatory coordination: Alignment among authorities, laws, standards, and policy instruments to reduce gaps or conflicting climate requirements. In Climate Policy Implementation, the focus is on the analysis, design, implementation, interpretation, or evaluation of regulatory coordination within Climate Change Law and Policy, particularly where the Climate Policy Implementation module establishes its technical context.', 'SSD_COURSE_052_M7_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_052_M7_S3', 'monitoring', '3', 'monitoring: Systematic collection and review of observations or measurements over time to determine status, compliance, performance, or change against defined criteria. In Climate Policy Implementation, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_052_M7_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_052_M7_S4', 'Policy evaluation', '4', 'Policy evaluation: Systematic assessment of climate policies or policy instruments against defined criteria such as effectiveness, efficiency, equity, feasibility, and implementation outcomes. In Climate Policy Implementation, the focus is on curricular scope: Climate Change Law and Policy; The concept is represented at the level of the stated mechanism, properties, constraints, and application criteria.', 'SSD_COURSE_052_M7_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_053_M1_S1', 'offer', '1', 'offer refers to a definite proposal made with the intention that acceptance can create a binding agreement, subject to applicable law. In Contract Formation, the focus is on the analysis, design, implementation, interpretation, or evaluation of offer within Contract Law and Commercial Agreements, particularly where the Contract Formation module establishes its technical context.', 'SSD_COURSE_053_M1_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_053_M1_S2', 'acceptance', '2', 'acceptance refers to an unqualified assent to an offer communicated in the legally required or agreed manner. In Contract Formation, the focus is on the analysis, design, implementation, interpretation, or evaluation of acceptance within Contract Law and Commercial Agreements, particularly where the Contract Formation module establishes its technical context.', 'SSD_COURSE_053_M1_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_053_M1_S3', 'consideration', '3', 'consideration refers to the legally recognised value exchanged in support of a contract where the applicable legal system requires it. In Contract Formation, the focus is on the analysis, design, implementation, interpretation, or evaluation of consideration within Contract Law and Commercial Agreements, particularly where the Contract Formation module establishes its technical context.', 'SSD_COURSE_053_M1_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_053_M1_S4', 'intention', '4', 'intention refers to the parties'' legally relevant intention to create binding obligations. In Contract Formation, the focus is on the analysis, design, implementation, interpretation, or evaluation of intention within Contract Law and Commercial Agreements, particularly where the Contract Formation module establishes its technical context.', 'SSD_COURSE_053_M1_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_053_M1_S5', 'capacity', '5', 'capacity refers to the legal ability of a person or entity to enter into an enforceable contract. In Contract Formation, the focus is on the analysis, design, implementation, interpretation, or evaluation of capacity within Contract Law and Commercial Agreements, particularly where the Contract Formation module establishes its technical context.', 'SSD_COURSE_053_M1_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_053_M1_S6', 'consent', '6', 'consent: Agreement given voluntarily and with sufficient understanding, without legally recognised defects such as coercion or undue influence. In Contract Formation, the focus is on the analysis, design, implementation, interpretation, or evaluation of consent within Contract Law and Commercial Agreements, particularly where the Contract Formation module establishes its technical context.', 'SSD_COURSE_053_M1_S6', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_053_M2_S1', 'express terms', '1', 'express terms: Contract terms stated explicitly by the parties, orally or in writing. In Contract Terms and Interpretation, the focus is on the analysis, design, implementation, interpretation, or evaluation of express terms within Contract Law and Commercial Agreements, particularly where the Contract Terms and Interpretation module establishes its technical context.', 'SSD_COURSE_053_M2_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_053_M2_S2', 'implied terms', '2', 'implied terms: Terms treated as part of a contract by law, custom, necessity, or the parties'' circumstances. In Contract Terms and Interpretation, the focus is on the analysis, design, implementation, interpretation, or evaluation of implied terms within Contract Law and Commercial Agreements, particularly where the Contract Terms and Interpretation module establishes its technical context.', 'SSD_COURSE_053_M2_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_053_M2_S3', 'conditions and warranties', '3', 'conditions and warranties: Contractual terms distinguished by the legal consequences attached to their breach. In Contract Terms and Interpretation, the focus is on the analysis, design, implementation, interpretation, or evaluation of conditions and warranties within Contract Law and Commercial Agreements, particularly where the Contract Terms and Interpretation module establishes its technical context.', 'SSD_COURSE_053_M2_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_053_M2_S4', 'interpretation', '4', 'interpretation: Determining the meaning and legal effect of contractual language in its context. In Contract Terms and Interpretation, the focus is on the analysis, design, implementation, interpretation, or evaluation of interpretation within Contract Law and Commercial Agreements, particularly where the Contract Terms and Interpretation module establishes its technical context.', 'SSD_COURSE_053_M2_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_053_M2_S5', 'exclusion clauses', '5', 'exclusion clauses: Contract terms that seek to limit or exclude specified liabilities or obligations, subject to applicable legal controls. In Contract Terms and Interpretation, the focus is on the analysis, design, implementation, interpretation, or evaluation of exclusion clauses within Contract Law and Commercial Agreements, particularly where the Contract Terms and Interpretation module establishes its technical context.', 'SSD_COURSE_053_M2_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_053_M3_S1', 'performance', '1', 'performance: Carrying out contractual obligations in accordance with the agreement and applicable law. In Performance and Discharge, the focus is on the analysis, design, implementation, interpretation, or evaluation of performance within Contract Law and Commercial Agreements, particularly where the Performance and Discharge module establishes its technical context.', 'SSD_COURSE_053_M3_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_053_M3_S2', 'frustration', '2', 'frustration refers to a doctrine that may discharge a contract when an unforeseen event fundamentally changes the nature of performance. In Performance and Discharge, the focus is on the analysis, design, implementation, interpretation, or evaluation of frustration within Contract Law and Commercial Agreements, particularly where the Performance and Discharge module establishes its technical context.', 'SSD_COURSE_053_M3_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_053_M3_S3', 'novation', '3', 'novation: Replacement of an existing contractual obligation or party with a new arrangement by agreement. In Performance and Discharge, the focus is on the analysis, design, implementation, interpretation, or evaluation of novation within Contract Law and Commercial Agreements, particularly where the Performance and Discharge module establishes its technical context.', 'SSD_COURSE_053_M3_S3', 'Semantically_Audited', 'Active', '4.0') ON CONFLICT DO NOTHING;